#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using ld = long double;
using pll = pair<ll, ll>;
using vll = vector<ll>;
using vbl = vector<bool>;
using vvll = vector<vll>;
using vld = vector<ld>;
using vb = vector<bool>;
using vc = vector<char>;
using vpll = vector<pll>;

template<typename T>
ostream& operator<<(ostream& os, const vector<T>& V) {
    os << "[ ";
    for (const auto& v : V) os << v << " ";
    return os << "]";
}

template<typename T>
ostream& operator<<(ostream& os, const set<T>& V) {
    os << "[ ";
    for (const auto& v : V) os << v << " ";
    return os << "]";
}

template<typename T, typename R>
ostream& operator<<(ostream& os, const map<T, R>& V) {
    os << "[ ";
    for (const auto& v : V) os << "(" << v.first << ":" << v.second << ")";
    return os << "]";
}

template<typename T, typename R>
ostream& operator<<(ostream& os, const pair<T, R>& V) {
    return os << "(" << V.first << "," << V.second << ")";
}

#define TRACE
#ifdef TRACE
    #define trace(...) __f(#__VA_ARGS__, __VA_ARGS__)
    template<typename Arg1>
    void __f(const char* name, Arg1&& arg1) {
        cerr << name << " : " << arg1 << endl;
    }
    template<typename Arg1, typename... Args>
    void __f(const char* names, Arg1&& arg1, Args&&... args) {
        const char* comma = strchr(names + 1, ',');
        cerr.write(names, comma - names) << " : " << arg1 << " | ";
        __f(comma + 1, args...);
    }
    clock_t clk = clock();
    #define checktime() cout << "\nTime Elapsed : " << float(clock() - clk) / CLOCKS_PER_SEC << endl
#else
    #define trace(...)
    #define checktime()
#endif

const ll MOD = 1000000007LL;
const ll MAX_N = 1000000LL;

void solve() {
    ll x, y, n;
    cin >> x >> y >> n;

    ll best_a = 0, best_b = 1;
    ld min_val = numeric_limits<ld>::max();

    for (ll i = 1; i <= n; ++i) {
        ll product = i * x;
        ll rem = product % y;
        ld diff = min(rem, y - rem);
        ld curr_val = diff / static_cast<ld>(i);

        if (curr_val < min_val) {
            min_val = curr_val;
            best_b = i;
            if (rem <= y - rem) {
                best_a = product / y;
            } else {
                best_a = product / y + 1;
            }
        }
    }

    cout << best_a << "/" << best_b << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    cout << fixed << setprecision(25);

    ll t = 1;
    while (t--) {
        solve();
    }
    return 0;
}
